1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
8	
9	/**
10	 * Validates the create-owner request's {@code postcode} when one is supplied.
11	 *
12	 * <p>Postcode is optional: an absent (or blank) postcode passes untouched, keeping the
13	 * request contract backward-compatible. When present it must be four digits and, when the
14	 * owner's city maps to a known region, must fall inside that region's inclusive range per
15	 * the fixed table (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
16	 * region accepts any 4-digit postcode. Anything else is rejected with an
17	 * {@link InvalidPostcodeException} (400). The valid, supplied value is left on the body so
18	 * {@link BuildOwner} stores and later steps return it.
19	 */
20	public class ValidatePostcode {
21	
22	    /** City -> canonical region, matching the fixed city-to-region table. */
23	    private static final Map<String, String> CITY_REGION =
24	            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
25	
26	    /** Region -> inclusive 4-digit postcode range {low, high}. */
27	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
28	            "NSW", new int[] {2000, 2099},
29	            "VIC", new int[] {3000, 3099},
30	            "QLD", new int[] {4000, 4099});
31	
32	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
33	        String postcode = request.getPostcode();
34	        if (postcode == null || postcode.isBlank()) {
35	            return; // optional when absent
36	        }
37	        if (!postcode.matches("[0-9]{4}")) {
38	            throw new InvalidPostcodeException("Postcode must be four digits");
39	        }
40	        String region = CITY_REGION.get(request.getCity());
41	        if (region == null) {
42	            return; // unknown region accepts any 4-digit postcode
43	        }
44	        int[] range = REGION_POSTCODES.get(region);
45	        int value = Integer.parseInt(postcode);
46	        if (value < range[0] || value > range[1]) {
47	            throw new InvalidPostcodeException(
48	                    "Postcode " + postcode + " is not valid for region " + region);
49	        }
50	    }
51	}
