3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Shared normalization of an owner's {@code address}, applied whenever an owner is
8	 * created. The canonical form is: trimmed, runs of whitespace collapsed to a single
9	 * space, upper-cased, and common street-type abbreviations expanded as whole words
10	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
11	 *
12	 * <p>So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"} and {@code "7 elm ave"}
13	 * becomes {@code "7 ELM AVENUE"}. The stored and returned address is this form, the
14	 * required-field check rejects an address that is blank after it, and every address
15	 * comparison (household duplicate detection and the shared household id) uses it.
16	 */
17	public final class AddressNormalizer {
18	
19	    /** Whole-word street-type abbreviations expanded to their canonical form. */
20	    private static final Map<String, String> ABBREVIATIONS = Map.of(
21	            "ST", "STREET",
22	            "RD", "ROAD",
23	            "AVE", "AVENUE");
24	
25	    private AddressNormalizer() {
26	    }
27	
28	    /**
29	     * Returns the canonical form of {@code raw}, or {@code null} when {@code raw} is
30	     * {@code null}. A value that is blank (or whitespace only) normalizes to the empty
31	     * string, which the required-field check treats as absent.
32	     */
33	    public static String normalize(String raw) {
34	        if (raw == null) {
35	            return null;
36	        }
37	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
38	        if (collapsed.isEmpty()) {
39	            return "";
40	        }
41	        String[] tokens = collapsed.split(" ");
42	        StringBuilder result = new StringBuilder(collapsed.length());
43	        for (int i = 0; i < tokens.length; i++) {
44	            if (i > 0) {
45	                result.append(' ');
46	            }
47	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
48	        }
49	        return result.toString();
50	    }
51	}
